import "server-only";
import type { Prisma } from "@/generated/prisma/client";
import { resolveUsagePeriods, type UsagePeriodSpec } from "@/lib/usage-periods";
import {
  reservationSelect,
  evidenceSelect,
  type AdminUser,
} from "./projections";
type Reservation = Prisma.UsageReservationGetPayload<{
  select: typeof reservationSelect;
}>;
type Evidence = Prisma.UsageImportEvidenceGetPayload<{
  select: typeof evidenceSelect;
}>;
// Same direct-assignment, overlap, and import de-duplication rules as the ledger.
export function countAdminUsage(
  period: Pick<UsagePeriodSpec, "kind" | "startsAt" | "operationalEndsAt"> & {
    id?: string;
  },
  reservations: Reservation[],
  evidence: Evidence[],
) {
  const contains = (at: Date) =>
    period.startsAt <= at && at < period.operationalEndsAt;
  const keys = new Set(reservations.map((r) => r.deliveryKey));
  let sent = 0,
    reserved = 0,
    importedSent = 0,
    importedReserved = 0;
  for (const r of reservations) {
    if (r.status === "RELEASED") continue;
    const direct =
      !!period.id &&
      (period.kind === "DAILY" ? r.dailyPeriodId : r.monthlyPeriodId) ===
        period.id;
    if (!direct && !(r.chargedAt && contains(r.chargedAt))) continue;
    if (r.status === "CONFIRMED") {
      sent++;
      if (!direct) importedSent++;
    } else {
      reserved++;
      if (!direct) importedReserved++;
    }
  }
  for (const e of evidence) {
    if (e.deliveryKey && keys.has(e.deliveryKey)) continue;
    if (contains(e.chargedAt)) {
      sent++;
      importedSent++;
    }
  }
  return { sent, reserved, importedSent, importedReserved };
}
type AdminAllowance = {
  sent: number;
  reserved: number;
  importedSent: number;
  importedReserved: number;
  limit: number;
  remaining: number;
  startsAt: string;
  endsAt: string;
  resetsAt: string;
  label: string;
};
type AdminUsage = {
  state: "UNVERIFIED" | "UNRESOLVED" | "VERIFIED";
  daily: AdminAllowance | null;
  monthly: AdminAllowance | null;
};
export async function readAdminUsage(
  tx: Prisma.TransactionClient,
  users: AdminUser[],
  now: Date,
) {
  const ids = users.map((u) => u.id);
  const [periods, reservations, evidence, unverified] = await Promise.all([
    tx.usagePeriod.findMany({
      where: { userId: { in: ids } },
      select: { id: true, userId: true, key: true },
    }),
    tx.usageReservation.findMany({
      where: { userId: { in: ids } },
      select: reservationSelect,
    }),
    tx.usageImportEvidence.findMany({
      where: { userId: { in: ids } },
      select: evidenceSelect,
    }),
    tx.$queryRaw<
      { userId: string }[]
    >`SELECT DISTINCT c."userId" FROM "AdminSendMetadata" s JOIN "Campaign" c ON c.id=s."campaignId" WHERE c."userId" IN (${PrismaJoin(ids)}) AND NOT EXISTS (SELECT 1 FROM "UsageReservation" r WHERE r."userId"=c."userId" AND r."sendId"=s.id) AND (s.status='QUEUED' OR s."deliveryState" IN ('ATTEMPTING','UNCERTAIN') OR (s.status IN ('SENT','REPLIED') AND NOT EXISTS (SELECT 1 FROM "UsageImportEvidence" e WHERE e."userId"=c."userId" AND e."deliveryKey"=s.id))) UNION SELECT DISTINCT d."userId" FROM "AdminReceiptMetadata" d WHERE d."userId" IN (${PrismaJoin(ids)}) AND NOT EXISTS (SELECT 1 FROM "UsageReservation" r WHERE r."userId"=d."userId" AND r."deliveryKey"=d."deliveryKey") AND NOT EXISTS (SELECT 1 FROM "UsageImportEvidence" e WHERE e."userId"=d."userId" AND e."deliveryKey"=d."deliveryKey")`,
  ]);
  return new Map<string, AdminUsage>(
    users.map((user) => {
      if (
        user.usageBackfillVersion < 1 ||
        unverified.some((r) => r.userId === user.id)
      )
        return [
          user.id,
          { state: "UNVERIFIED" as const, daily: null, monthly: null },
        ];
      let specs;
      try {
        specs = resolveUsagePeriods(user, now);
      } catch {
        return [
          user.id,
          { state: "UNRESOLVED" as const, daily: null, monthly: null },
        ];
      }
      const rs = reservations.filter((r) => r.userId === user.id),
        es = evidence.filter((e) => e.userId === user.id);
      const allowance = (spec: UsagePeriodSpec) => {
        const p = periods.find(
          (p) => p.userId === user.id && p.key === spec.key,
        );
        const counts = countAdminUsage({ ...spec, id: p?.id }, rs, es);
        // A missing bucket may have uncharged queue reservations in an old bucket.
        // New credit is not claimed until normal lifecycle processing rebinds them.
        const pending = rs.filter(
          (r) =>
            r.status === "RESERVED" &&
            !r.chargedAt &&
            (spec.kind === "DAILY" ? r.dailyPeriodId : r.monthlyPeriodId) !==
              p?.id,
        ).length;
        return {
          ...counts,
          reserved: counts.reserved + pending,
          limit: spec.limit,
          remaining: Math.max(
            0,
            spec.limit - counts.sent - counts.reserved - pending,
          ),
          startsAt: spec.startsAt.toISOString(),
          endsAt: spec.endsAt.toISOString(),
          resetsAt: spec.operationalEndsAt.toISOString(),
          label:
            spec.kind === "DAILY"
              ? "UTC day"
              : spec.key.startsWith("provider:")
                ? "Provider billing period"
                : "UTC calendar month",
        };
      };
      return [
        user.id,
        {
          state: "VERIFIED" as const,
          daily: allowance(specs.daily),
          monthly: allowance(specs.monthly),
        },
      ];
    }),
  );
}
// Static SQL fragments still use Prisma's parameterization for every owner UUID.
import { Prisma as PrismaRuntime } from "@/generated/prisma/client";
function PrismaJoin(ids: string[]) {
  return ids.length ? PrismaRuntime.join(ids) : PrismaRuntime.sql`NULL`;
}
